register("src.logger", function()
-- Wires extractors to GameEvents hooks and streams encoded records
-- to a sink. A logging failure must never escape into the game, so
-- extractor errors become logger_error records instead of being raised.
local json = _require("src.json")

local M = {}

local function errorRecord(hookName, err)
  return { event = "logger_error", hook = hookName, error = tostring(err) }
end

local function handler(deps, name, extractor)
  return function(...)
    local ok, record = pcall(extractor, deps.civ, ...)
    if ok and record == nil then return end
    if not ok then record = errorRecord(name, record) end
    deps.sink(json.encode(record))
  end
end

-- Extractors named in UpperCamelCase are GameEvents hooks; lowercase
-- names are helpers emitted explicitly (see docs/design-decisions.md).
function M.attach(deps)
  for name, extractor in pairs(deps.extractors) do
    if name:match("^%u") then
      deps.events[name].Add(handler(deps, name, extractor))
    end
  end
end

function M.emit(deps, name, extractor, ...)
  handler(deps, name, extractor)(...)
end

return M
end)

register("src.census", function()
-- Keeps a per-player city census between turns and emits city_destroyed
-- when a known city disappears. Razing fires no DLL hook (CvCity::
-- DoRazingTurn -> CvPlayer::disband contains no CallHook), so this is
-- polled once per player per turn via PlayerDoTurn rather than pushed
-- as an event. Registered directly on PlayerDoTurn (bypassing
-- logger.attach) since it needs cross-turn state and may emit zero or
-- more records per firing, unlike the one-hook-one-record extractors.
local json = _require("src.json")

local M = {}

local function errorRecord(err)
  return { event = "logger_error", hook = "PlayerDoTurn (census)", error = tostring(err) }
end

function M.new(civ, sink)
  local known = {}

  local function poll(playerId)
    local current = civ.citySet(playerId)
    for cityId, city in pairs(known[playerId] or {}) do
      if not current[cityId] then
        sink(json.encode({
          event = "city_destroyed",
          turn = civ.turn(),
          civ = civ.civName(playerId),
          city = city.name,
          x = city.x,
          y = city.y,
        }))
      end
    end
    known[playerId] = current
  end

  return function(playerId)
    local ok, err = pcall(poll, playerId)
    if not ok then sink(json.encode(errorRecord(err))) end
  end
end

return M
end)

register("src.cities", function()
-- Writes one city_snapshot per city per turn. Cities are where the
-- decisions happen and the log has only ever described them through the
-- events that befall them: nothing has ever carried what a city is
-- building, how much damage it is taking, or whether it can be governed
-- at all. Registered directly on PlayerDoTurn like the other pollers,
-- since it emits many records per firing; unlike them it keeps no state
-- and diffs nothing - every city is written every turn, and the
-- filtering belongs downstream.
local json = _require("src.json")

local M = {}

local function errorRecord(err)
  return { event = "logger_error", hook = "PlayerDoTurn (cities)", error = tostring(err) }
end

function M.new(civ, sink)
  local function poll(playerId)
    local turn, name = civ.turn(), civ.civName(playerId)
    for _, record in ipairs(civ.cityStats(playerId)) do
      record.event = "city_snapshot"
      record.turn = turn
      record.civ = name
      sink(json.encode(record))
    end
  end

  return function(playerId)
    local ok, err = pcall(poll, playerId)
    if not ok then sink(json.encode(errorRecord(err))) end
  end
end

return M
end)

register("src.free_buildings", function()
-- Emits building_granted when a city acquires a building nobody built.
-- The DLL hands out free buildings without firing CityConstructed:
-- CvCity.cpp:7391 takes the FreeBuildingThisCity path straight to
-- SetNumFreeBuilding, well clear of the three hook call sites, and the
-- trait and policy grants at CvCity.cpp:486 and 525 do the same. Angkor
-- Wat's University, Hagia Sophia's Temple and Carthage's harbours have
-- therefore always been invisible to the log. Polled and diffed like
-- src/census.lua, for the same reason: nothing pushes them.
local json = _require("src.json")

local M = {}

local function errorRecord(err)
  return { event = "logger_error", hook = "PlayerDoTurn (free_buildings)", error = tostring(err) }
end

local function setOf(list)
  local set = {}
  for _, item in ipairs(list) do set[item] = true end
  return set
end

function M.new(civ, sink)
  local known, candidates, everything = {}, nil, nil

  local function announce(turn)
    local classes
    candidates, classes = civ.grantableBuildings()
    everything = civ.allBuildings()
    sink(json.encode({
      event = "free_buildings_ready",
      turn = turn,
      buildings = #candidates,
      all_buildings = #everything,
      classes = classes,
    }))
  end

  -- Nothing stands in the opening turns, so a fresh game has nothing to
  -- seed from and everything to report. A session resumed from a save
  -- starts with a Lua state that knows nothing, and reporting there would
  -- date every free building in the empire to the turn of the reload.
  local function seeding(playerId, turn)
    return known[playerId] == nil and turn > 1
  end

  -- City ids come back from a free list, so an id alone does not say the
  -- city is the one we saw last turn. Nothing means we have never looked
  -- at this city.
  local function heldLastTurn(playerId, city)
    local previous = (known[playerId] or {})[city.id]
    if previous and previous.name == city.name then return previous.buildings end
  end

  -- A captured city keeps the founding turn of whoever founded it
  -- (CvPlayer.cpp:2851), so the two turns agree only for a city this
  -- player founded. A city founded during the last turn is first seen now.
  local function foundedSincePoll(city, turn)
    return city.founded == city.acquired and city.founded >= turn - 1
  end

  local function grant(turn, name, city, building, source)
    sink(json.encode({
      event = "building_granted", turn = turn, civ = name,
      city = city, building = building, source = source,
    }))
  end

  -- A city founded since the last poll was built by nobody, so everything
  -- standing in it was handed over - including the real buildings mod
  -- scripts add through SetNumRealBuildingClass, which fire no hook and
  -- never show up as free. Every other city is a diff, and a city first
  -- seen without having just been founded is somebody else's work.
  local function report(playerId, city, turn, name)
    local before = heldLastTurn(playerId, city)
    if before then
      for _, building in ipairs(city.buildings) do
        if not before[building] then grant(turn, name, city.name, building, "diff") end
      end
    elseif foundedSincePoll(city, turn) then
      for _, building in ipairs(civ.cityBuildings(playerId, city.id, everything)) do
        grant(turn, name, city.name, building, "new_city")
      end
    end
  end

  local function poll(playerId)
    local turn, name = civ.turn(), civ.civName(playerId)
    if not candidates then announce(turn) end
    local silent, current = seeding(playerId, turn), {}

    for _, city in ipairs(civ.freeBuildings(playerId, candidates)) do
      if not silent then report(playerId, city, turn, name) end
      current[city.id] = { name = city.name, buildings = setOf(city.buildings) }
    end
    known[playerId] = current
  end

  return function(playerId)
    local ok, err = pcall(poll, playerId)
    if not ok then sink(json.encode(errorRecord(err))) end
  end
end

return M
end)

register("src.roster", function()
-- Announces eliminations. Nothing pushes them: CvPlayer::setAlive calls
-- no hook, and a dead player takes no turn, so the only trace in the log
-- today is that civ.playerStats stops answering and the snapshot stream
-- quietly ends. This polls the roster of living majors once per turn and
-- reports whoever left it, together with who ended up holding their
-- original capital - the difference between a conquest and a collapse.
--
-- The first poll of a session records a baseline: a reload must not
-- report every civ that fell before it as newly eliminated.
local json = _require("src.json")

local M = {}

local function errorRecord(err)
  return { event = "logger_error", hook = "PlayerDoTurn (roster)", error = tostring(err) }
end

-- pairs() order is undefined, and the log is compared line by line.
local function sortedIds(majors)
  local ids = {}
  for id in pairs(majors) do table.insert(ids, id) end
  table.sort(ids)
  return ids
end

local function reportFallen(civ, sink, turn, known, majors)
  for _, id in ipairs(sortedIds(known)) do
    if not majors[id] then
      sink(json.encode({
        event = "player_eliminated",
        turn = turn,
        civ = known[id],
        capital_held_by = civ.capitalHolder(id),
      }))
    end
  end
end

function M.new(civ, sink)
  local state = { turn = nil, known = nil }

  local function poll()
    local turn = civ.turn()
    if turn == state.turn then return end
    state.turn = turn

    local majors = civ.livingMajors()
    if state.known then reportFallen(civ, sink, turn, state.known, majors) end
    state.known = majors
  end

  return function()
    local ok, err = pcall(poll)
    if not ok then sink(json.encode(errorRecord(err))) end
  end
end

return M
end)

register("src.congress", function()
-- Polls the World Congress once per turn and diffs it into events. No
-- GameEvents hook covers the Congress (mp_vote/mp_proposal_result are
-- Lekmod's own multiplayer voting, unrelated), so the league state is
-- read via Game.GetActiveLeague() and compared turn to turn. Registered
-- directly on PlayerDoTurn (bypassing logger.attach) since it needs
-- cross-turn state, may emit zero or more records per firing, and must
-- emit congress_snapshot once per turn even though PlayerDoTurn fires
-- once per player.
local json = _require("src.json")

local M = {}

local function errorRecord(err)
  return { event = "logger_error", hook = "PlayerDoTurn (congress)", error = tostring(err) }
end

local function diffProposed(sink, turn, known, current)
  for id, proposal in pairs(current) do
    if not known[id] then
      sink(json.encode({
        event = "resolution_proposed",
        turn = turn,
        resolution = proposal.type,
        proposer = proposal.proposer,
        repeal = proposal.repeal,
      }))
    end
  end
end

-- A repeal proposal carries the ID of the resolution it targets (the DLL's
-- CvRepealProposal is constructed with pResolution->GetID()), so an active
-- resolution still sitting under the proposal's ID means the opposite for a
-- repeal than it does for an enactment: the target survived the vote.
local function ongoingOutcome(proposal, snapshot)
  local targetActive = snapshot.active_resolutions[proposal.id] ~= nil
  local passed = (proposal.repeal == true) ~= targetActive
  return passed and "resolution_passed" or "resolution_failed"
end

local function projectRunning(projects, projectType)
  local project = projects[projectType]
  return project ~= nil and (project.active or project.complete)
end

-- A resolution with only one-time effects expires the moment it is enacted
-- and never joins the active resolutions, so the test above would answer
-- "failed" for it whatever the vote did. The one trace an enactment leaves
-- is the league project it starts; without one there is nothing to read,
-- and a project that was already running before the vote is a state the
-- game does not allow (CvVotingClasses.cpp:2751) rather than a verdict.
local function oneShotOutcome(proposal, known, snapshot)
  local project = proposal.league_project
  if not project then return "resolution_undetermined" end
  if not projectRunning(snapshot.projects, project) then return "resolution_failed" end
  if projectRunning(known.projects, project) then return "resolution_undetermined" end
  return "resolution_passed"
end

local function outcome(proposal, known, snapshot)
  if proposal.ongoing_effects then return ongoingOutcome(proposal, snapshot) end
  return oneShotOutcome(proposal, known, snapshot)
end

local function diffResolved(sink, turn, known, snapshot)
  for id, proposal in pairs(known.proposals) do
    if not snapshot.proposals[id] then
      sink(json.encode({
        event = outcome(proposal, known, snapshot),
        turn = turn,
        resolution = proposal.type,
      }))
    end
  end
end

local function diffRepealed(sink, turn, known, current)
  for id, resolution in pairs(known) do
    if not current[id] then
      sink(json.encode({
        event = "resolution_repealed", turn = turn, resolution = resolution.type,
      }))
    end
  end
end

local function diff(sink, turn, known, snapshot)
  if known.host ~= snapshot.host then
    sink(json.encode({
      event = "congress_host_changed", turn = turn,
      old_host = known.host, new_host = snapshot.host,
    }))
  end
  if snapshot.united_nations and not known.united_nations then
    sink(json.encode({ event = "united_nations_formed", turn = turn }))
  end
  diffProposed(sink, turn, known.proposals, snapshot.proposals)
  diffResolved(sink, turn, known, snapshot)
  diffRepealed(sink, turn, known.active_resolutions, snapshot.active_resolutions)
end

function M.new(civ, sink)
  local state = { turn = nil, snapshot = nil }

  local function poll()
    local turn = civ.turn()
    if turn == state.turn then return end
    state.turn = turn

    local snapshot = civ.congressSnapshot()
    if not snapshot then
      state.snapshot = nil
      return
    end

    if not state.snapshot then
      sink(json.encode({ event = "congress_founded", turn = turn, host = snapshot.host }))
    else
      diff(sink, turn, state.snapshot, snapshot)
    end

    sink(json.encode({
      event = "congress_snapshot",
      turn = turn,
      host = snapshot.host,
      delegates = snapshot.delegates,
      votes_needed_for_diplo_victory = snapshot.votes_needed_for_diplo_victory,
    }))

    state.snapshot = snapshot
  end

  return function(playerId)
    local ok, err = pcall(poll, playerId)
    if not ok then sink(json.encode(errorRecord(err))) end
  end
end

return M
end)

register("src.victory", function()
-- Announces the end of the game exactly once. A per-turn poll cannot:
-- the game stops on the turn it is decided, so the last PlayerDoTurn
-- never comes. GameCoreTestVictory does, because CvGame::testVictory
-- fires it above its own "already decided" guard (CvGame.cpp:9943), and
-- keeps firing on player death, team change and concluded Congress
-- votes afterwards - hence the one-shot flag. The DLL calls this hook
-- "to allow a Lua script to set the victory state", so the handler
-- returns nothing: reading is safe, answering would not be.
local json = _require("src.json")

local M = {}

local function errorRecord(err)
  return { event = "logger_error", hook = "GameCoreTestVictory", error = tostring(err) }
end

function M.new(civ, sink)
  local announced = false

  local function watch()
    if announced then return end
    local result = civ.victory()
    if not result then return end
    announced = true
    sink(json.encode({
      event = "game_ended",
      turn = civ.turn(),
      winner_team = result.winner_team,
      winner_civs = result.winner_civs,
      victory = result.victory,
      winning_turn = result.winning_turn,
    }))
  end

  return function()
    local ok, err = pcall(watch)
    if not ok then sink(json.encode(errorRecord(err))) end
  end
end

return M
end)

register("src.diplomacy", function()
-- Polls the state between every pair of living majors once per turn and
-- diffs it into events. Only war and peace have hooks (DeclareWar,
-- MakePeace); friendships, pacts, open borders and embassies are state
-- nobody announces, so they are read and compared turn to turn.
-- Registered directly on PlayerDoTurn like the other stateful pollers,
-- and gated on the turn because the pairwise state is game-global while
-- PlayerDoTurn fires once per living player.
--
-- The first poll of a session only records a baseline: a reload must not
-- re-announce friendships that have stood for fifty turns.
local json = _require("src.json")

local M = {}

-- The DLL sets DoF, defensive pacts and trade agreements on both sides,
-- so those are one fact about a pair and are read from the lower player
-- id only. Open borders and embassies belong to the side that granted
-- them and are reported per direction.
local MUTUAL = {
  { flag = "dof", up = "friendship_declared", down = "friendship_ended" },
  { flag = "defensive_pact", up = "defensive_pact_signed", down = "defensive_pact_ended" },
  { flag = "trade_agreement", up = "trade_agreement_signed", down = "trade_agreement_ended" },
}

local ONE_SIDED = {
  { flag = "open_borders", up = "open_borders_granted", down = "open_borders_revoked" },
  { flag = "embassy", up = "embassy_established", down = "embassy_ended" },
}

local function errorRecord(err)
  return { event = "logger_error", hook = "PlayerDoTurn (diplomacy)", error = tostring(err) }
end

-- pairs() order is undefined, and the log is compared line by line.
local function sortedIds(snapshot)
  local ids = {}
  for id in pairs(snapshot) do table.insert(ids, id) end
  table.sort(ids)
  return ids
end

local function changed(known, current, flag)
  if not known or not current then return nil end
  if known[flag] == current[flag] then return nil end
  return current[flag]
end

local function diffMutual(civ, sink, turn, known, current, a, b)
  for _, fact in ipairs(MUTUAL) do
    local now = changed(known, current, fact.flag)
    if now ~= nil then
      sink(json.encode({
        event = now and fact.up or fact.down,
        turn = turn,
        civs = { civ.civName(a), civ.civName(b) },
      }))
    end
  end
end

local function diffOneSided(civ, sink, turn, known, current, a, b)
  for _, fact in ipairs(ONE_SIDED) do
    local now = changed(known, current, fact.flag)
    if now ~= nil then
      sink(json.encode({
        event = now and fact.up or fact.down,
        turn = turn,
        civ = civ.civName(a),
        other_civ = civ.civName(b),
      }))
    end
  end
end

local function diffPair(civ, sink, turn, known, current, a, b)
  if a < b then diffMutual(civ, sink, turn, known, current, a, b) end
  diffOneSided(civ, sink, turn, known, current, a, b)
end

local function diff(civ, sink, turn, known, snapshot)
  for _, a in ipairs(sortedIds(snapshot)) do
    for _, b in ipairs(sortedIds(snapshot[a])) do
      diffPair(civ, sink, turn, (known[a] or {})[b], snapshot[a][b], a, b)
    end
  end
end

function M.new(civ, sink)
  local state = { turn = nil, snapshot = nil }

  local function poll()
    local turn = civ.turn()
    if turn == state.turn then return end
    state.turn = turn

    local snapshot = civ.diplomacySnapshot()
    if state.snapshot then diff(civ, sink, turn, state.snapshot, snapshot) end
    state.snapshot = snapshot
  end

  return function()
    local ok, err = pcall(poll)
    if not ok then sink(json.encode(errorRecord(err))) end
  end
end

return M
end)

register("src.city_states", function()
-- Polls where every major stands with every city-state and writes what
-- the three city_state_* hooks cannot say. Those fire only when a
-- threshold is crossed; between them the log never says whether an
-- alliance is held at 112 and sliding or at 61 and about to go.
--
-- A session opens with the standing state of every city-state, so a
-- resumed log is not blind until somebody happens to cross a threshold,
-- and a city-state nobody ever courts still appears. After that only a
-- crossed threshold is written: influence moves every turn on its own,
-- and recording that would be most of the log to say that decay is
-- decay. The per_turn rate in each record is what makes the gap
-- readable - the curve between two snapshots follows from it.
--
-- Pledges to protect are the exception, written whenever they change:
-- no hook covers them at all, and a discrete political act should not
-- wait for somebody else to cross a threshold.
--
-- Registered on PlayerDoTurn like the other stateful pollers and gated
-- on the turn, because the state is game-global while PlayerDoTurn
-- fires once per living player.
local json = _require("src.json")

local M = {}

local function errorRecord(err)
  return { event = "logger_error", hook = "PlayerDoTurn (city states)", error = tostring(err) }
end

-- pairs() order is undefined, and the log is compared line by line.
local function sortedIds(t)
  local ids = {}
  for id in pairs(t) do table.insert(ids, id) end
  table.sort(ids)
  return ids
end

local function relationList(relations)
  local list = {}
  for _, id in ipairs(sortedIds(relations)) do
    table.insert(list, relations[id])
  end
  return list
end

local function writeSnapshot(sink, turn, entry)
  local relations = relationList(entry.relations)
  sink(json.encode({
    event = "city_state_snapshot",
    turn = turn,
    city_state = entry.civ,
    ally = entry.ally,
    relations = #relations > 0 and relations or nil,
  }))
end

local function levelWith(entry, majorId)
  local relation = entry.relations[majorId]
  return relation and relation.level
end

local function levelChanged(known, current)
  for majorId in pairs(known.relations) do
    if levelWith(known, majorId) ~= levelWith(current, majorId) then return true end
  end
  for majorId in pairs(current.relations) do
    if levelWith(known, majorId) ~= levelWith(current, majorId) then return true end
  end
  return false
end

local function diffPledges(sink, turn, known, current)
  for _, majorId in ipairs(sortedIds(current.relations)) do
    local relation = current.relations[majorId]
    local was = (known.relations[majorId] or {}).protected
    if was ~= relation.protected then
      sink(json.encode({
        event = relation.protected and "city_state_protected"
          or "city_state_protection_ended",
        turn = turn,
        city_state = current.civ,
        civ = relation.civ,
      }))
    end
  end
end

local function diff(sink, turn, known, snapshot)
  for _, minorId in ipairs(sortedIds(snapshot)) do
    local entry, previous = snapshot[minorId], known[minorId]
    if not previous then
      writeSnapshot(sink, turn, entry)
    else
      diffPledges(sink, turn, previous, entry)
      if levelChanged(previous, entry) then writeSnapshot(sink, turn, entry) end
    end
  end
end

local function writeBaseline(sink, turn, snapshot)
  for _, minorId in ipairs(sortedIds(snapshot)) do
    writeSnapshot(sink, turn, snapshot[minorId])
  end
end

function M.new(civ, sink)
  local state = { turn = nil, snapshot = nil }

  local function poll()
    local turn = civ.turn()
    if turn == state.turn then return end
    state.turn = turn

    local snapshot = civ.cityStateSnapshot()
    if state.snapshot then
      diff(sink, turn, state.snapshot, snapshot)
    else
      writeBaseline(sink, turn, snapshot)
    end
    state.snapshot = snapshot
  end

  return function()
    local ok, err = pcall(poll)
    if not ok then sink(json.encode(errorRecord(err))) end
  end
end

return M
end)

register("src.trade_routes", function()
-- Polls the trade routes in play and diffs them into events. A route is
-- a deal, and the log has never said what either party got out of one:
-- today there is a single trade_route_plundered and no record of what
-- was plundered or who lost it.
--
-- Diffed rather than snapshotted because a route stands for tens of
-- turns and its terms are fixed when it opens. Two records over its life
-- say everything a per-turn stream would.
--
-- The first poll of a session is only a baseline: a reload must not
-- re-announce sixty routes that were each announced when they opened.
--
-- Registered on PlayerDoTurn like the other stateful pollers and gated
-- on the turn, because the route list is game-global while PlayerDoTurn
-- fires once per living player.
local json = _require("src.json")

local M = {}

local function errorRecord(err)
  return { event = "logger_error", hook = "PlayerDoTurn (trade routes)", error = tostring(err) }
end

-- pairs() order is undefined, and the log is compared line by line.
local function sortedKeys(t)
  local keys = {}
  for key in pairs(t) do table.insert(keys, key) end
  table.sort(keys)
  return keys
end

local function establishedRecord(turn, route)
  local record = { event = "trade_route_established", turn = turn }
  for field, value in pairs(route) do record[field] = value end
  return record
end

-- Only which route ended. What it was worth was said when it opened, and
-- a plundered route is told from an expired one by the
-- trade_route_plundered of the same turn.
local function endedRecord(turn, route)
  return {
    event = "trade_route_ended",
    turn = turn,
    civ = route.civ,
    from_city = route.from_city,
    to_civ = route.to_civ,
    to_city = route.to_city,
  }
end

local function diff(sink, turn, known, routes)
  for _, key in ipairs(sortedKeys(routes)) do
    if not known[key] then
      sink(json.encode(establishedRecord(turn, routes[key])))
    end
  end
  for _, key in ipairs(sortedKeys(known)) do
    if not routes[key] then
      sink(json.encode(endedRecord(turn, known[key])))
    end
  end
end

function M.new(civ, sink)
  local state = { turn = nil, routes = nil }

  local function poll()
    local turn = civ.turn()
    if turn == state.turn then return end
    state.turn = turn

    local routes = civ.tradeRoutes()
    if state.routes then diff(sink, turn, state.routes, routes) end
    state.routes = routes
  end

  return function()
    local ok, err = pcall(poll)
    if not ok then sink(json.encode(errorRecord(err))) end
  end
end

return M
end)

register("src.spies", function()
-- Polls every major's spies and diffs them into events. Espionage fires
-- no hook at all - CvEspionageClasses.cpp calls LuaSupport::Call not
-- once - so nothing here is pushed and all of it is read.
--
-- The state cycle a spy runs after being posted is fixed by where it was
-- sent: travelling, surveillance, then gathering intel in a foreign
-- city, rigging elections in a city-state, or counter-intelligence at
-- home. Logging each of those turns would be four fifths of the records
-- to say what the destination already says, so the posting is written
-- and the cycle is not. The one turn in the cycle worth a record is when
-- surveillance goes true: from then on the spy's owner can see the city.
--
-- The first poll of a session is only a baseline.
--
-- Registered on PlayerDoTurn like the other stateful pollers and gated
-- on the turn: the whole board is read at once while PlayerDoTurn fires
-- once per living player.
local json = _require("src.json")

local M = {}

local function errorRecord(err)
  return { event = "logger_error", hook = "PlayerDoTurn (spies)", error = tostring(err) }
end

-- pairs() order is undefined, and the log is compared line by line.
local function sortedKeys(t)
  local keys = {}
  for key in pairs(t) do table.insert(keys, key) end
  table.sort(keys)
  return keys
end

local function record(event, turn, spy, extra)
  local out = { event = event, turn = turn, civ = spy.civ, spy = spy.spy }
  for field, value in pairs(extra or {}) do out[field] = value end
  return out
end

local function at(spy)
  return { city = spy.city, city_civ = spy.city_civ }
end

local function posting(spy)
  return { city = spy.city, city_civ = spy.city_civ,
           x = spy.x, y = spy.y, state = spy.state }
end

local function completion(spy)
  return { city = spy.city, city_civ = spy.city_civ, state = spy.state }
end

local function moved(known, spy)
  return spy.x ~= nil and (known.x ~= spy.x or known.y ~= spy.y)
end

-- A counterspy sits in one of its owner's own cities and its progress is
-- always nil, so a completed mission can never surface it: spy_moved is
-- the only event it produces. When it was posted home to coordinates
-- that did not change, the move check misses it, and the transition into
-- counter_intel is the posting instead.
local function becameCounterspy(known, spy)
  return spy.state == "counter_intel" and known.state ~= "counter_intel"
    and spy.city ~= nil
end

-- A finished mission neither moves the spy nor changes its state: the
-- DLL resets the progress and sets the same activity going again
-- (CvEspionageClasses.cpp:807-810 for a stolen tech, :900-903 for a
-- rigged election). Progress otherwise only climbs, so a fall in place
-- is the completion. A fall that comes with a move is the new posting,
-- and a fall that comes with a state change is only the shared
-- travelling/surveillance/gathering-intel counter restarting.
local function completed(known, spy)
  return known.progress ~= nil and spy.progress ~= nil
    and known.state == spy.state
    and spy.progress < known.progress
end

local function diffSpy(sink, turn, known, spy)
  if known.state == "dead" then
    if spy.state ~= "dead" then
      sink(json.encode(record("spy_revived", turn, spy)))
      -- A revived spy is a fresh recruit with no prior position, so any
      -- city it already sits in is a new posting nothing else would see.
      -- The dead record it is diffed against carries no rank or progress
      -- worth trusting, so only the posting is read from it.
      if spy.x ~= nil then
        sink(json.encode(record("spy_moved", turn, spy, posting(spy))))
      end
    end
    return
  end
  if spy.state == "dead" then
    -- The DLL empties the location before setting SPY_STATE_DEAD, so the
    -- death site is the city the spy held on the last live poll.
    sink(json.encode(record("spy_killed", turn, spy, at(known))))
    return
  end
  if known.rank ~= spy.rank then
    sink(json.encode(record("spy_promoted", turn, spy, { rank = spy.rank })))
  end
  if moved(known, spy) or becameCounterspy(known, spy) then
    sink(json.encode(record("spy_moved", turn, spy, posting(spy))))
  elseif completed(known, spy) then
    sink(json.encode(record("spy_mission_completed", turn, spy, completion(spy))))
  end
  if not known.surveillance and spy.surveillance then
    sink(json.encode(record("spy_surveillance_established", turn, spy, at(spy))))
  end
end

local function diff(sink, turn, known, spies)
  for _, key in ipairs(sortedKeys(spies)) do
    if known[key] then
      diffSpy(sink, turn, known[key], spies[key])
    else
      sink(json.encode(record("spy_created", turn, spies[key], at(spies[key]))))
    end
  end
end

function M.new(civ, sink)
  local state = { turn = nil, spies = nil }

  local function poll()
    local turn = civ.turn()
    if turn == state.turn then return end
    state.turn = turn

    local spies = civ.spies()
    if state.spies then diff(sink, turn, state.spies, spies) end
    state.spies = spies
  end

  return function()
    local ok, err = pcall(poll)
    if not ok then sink(json.encode(errorRecord(err))) end
  end
end

return M
end)

register("src.main", function()
-- Entry point: gate on the local opt-in flag, then wire the logger
-- to the real game. Receives the game globals as a table so tests
-- (and the in-game loader) decide what "real" means.
local adapter = _require("src.adapter")
local extractors = _require("src.extractors")
local logger = _require("src.logger")
local census = _require("src.census")
local cities = _require("src.cities")
local freeBuildings = _require("src.free_buildings")
local roster = _require("src.roster")
local congress = _require("src.congress")
local victory = _require("src.victory")
local diplomacy = _require("src.diplomacy")
local cityStates = _require("src.city_states")
local tradeRoutes = _require("src.trade_routes")
local spies = _require("src.spies")

local M = {}

function M.enabled(modding)
  local data = modding.OpenUserData("civ-narrative-logger", 1)
  local value = data.GetValue("enabled")
  return value == 1 or value == "1"
end

function M.start(g)
  if not M.enabled(g.Modding) then return end
  local deps = {
    events = g.GameEvents,
    extractors = extractors,
    civ = adapter.new(g),
    sink = function(line) g.print("CIVLOG|" .. line) end,
  }
  logger.attach(deps)
  logger.emit(deps, "sessionStarted", extractors.sessionStarted)
  g.GameEvents.PlayerDoTurn.Add(census.new(deps.civ, deps.sink))
  g.GameEvents.PlayerDoTurn.Add(cities.new(deps.civ, deps.sink))
  g.GameEvents.PlayerDoTurn.Add(freeBuildings.new(deps.civ, deps.sink))
  g.GameEvents.PlayerDoTurn.Add(roster.new(deps.civ, deps.sink))
  g.GameEvents.PlayerDoTurn.Add(congress.new(deps.civ, deps.sink))
  g.GameEvents.PlayerDoTurn.Add(diplomacy.new(deps.civ, deps.sink))
  g.GameEvents.PlayerDoTurn.Add(cityStates.new(deps.civ, deps.sink))
  g.GameEvents.PlayerDoTurn.Add(tradeRoutes.new(deps.civ, deps.sink))
  g.GameEvents.PlayerDoTurn.Add(spies.new(deps.civ, deps.sink))
  g.GameEvents.GameCoreTestVictory.Add(victory.new(deps.civ, deps.sink))
end

return M
end)

_require("src.main").start({
  Game = Game,
  Players = Players,
  Teams = Teams,
  Map = Map,
  GameInfo = GameInfo,
  GameDefines = GameDefines,
  PreGame = PreGame,
  GameEvents = GameEvents,
  Modding = Modding,
  YieldTypes = YieldTypes,
  PublicOpinionTypes = PublicOpinionTypes,
  GameInfoTypes = GameInfoTypes,
  print = print,
})
